/**
  Harry Saltzman (Dr. No, From Russia with love, Goldfinger, Thunderball, You only live twice, On her Majesty's secret service, Diamonds are forever, Live and let die, The man with the golden gun)
 */
INSERT INTO producers (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('bb03f9e2-8290-491e-8216-85465ccfa304'),
       'Harry Saltzman',
       'Herschel "Harry" Saltzman was born on October 27, 1915, in Sherbrooke, Quebec, Canada. He began his show business career at a young age, working in vaudeville promotion, circus management, and stage productions across North America and Europe before serving in World War II. Following the war, Saltzman established himself as a prominent theatre and television producer in Paris and the United States before relocating to Great Britain in the mid-1950s. There, he co-founded Woodfall Film Productions with playwright John Osborne and director Tony Richardson, producing acclaimed British "kitchen sink" realism dramas such as Look Back in Anger and Saturday Night and Sunday Morning. In 1961, Saltzman acquired the screen option rights to Ian Fleming''s James Bond novels. Realizing he needed additional backing to turn the books into major feature films, he partnered with American producer Albert R. "Cubby" Broccoli to form Eon Productions and holding company Danjaq. The duo launched the cinematic franchise with Dr. No in 1962 starring Sean Connery, creating an unprecedented global movie phenomenon. Saltzman co-produced the first nine official James Bond entries alongside Broccoli, concluding his tenure with 1974''s The Man with the Golden Gun. Beyond the 007 franchise, Saltzman produced a variety of film projects, most notably adapting Len Deighton''s spy novels into the acclaimed Harry Palmer film trilogy starring Michael Caine, which began with The Ipcress File in 1965. He also produced the World War II aerial epic Battle of Britain in 1969. Following mounting financial pressures from external business investments, Saltzman sold his 50% share of the Bond franchise to United Artists in 1975 and largely stepped back from filmmaking. He passed away from a heart attack in Paris on September 28, 1994, at the age of 78, leaving behind a lasting legacy as one of the chief architects of modern blockbuster cinema.',
       'Canadian',
       '1915-10-27',
       '1994-09-28',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Albert R. Broccoli (Dr. No, From Russia with love, Goldfinger, Thunderball, You only live twice, On her Majesty's secret service, Diamonds are forever, Live and let die, The man with the golden gun, the spy who loved me, Moonraker, For your eyes only, Octopussy, A view to a kill, The living daylights, License to kill)
 */
INSERT INTO producers (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('058a1c47-5a9e-4ea7-b44b-50c9f426f050'),
       'Albert R. Broccoli',
       'Albert Romolo "Cubby" Broccoli was born on April 5, 1909, in Astoria, Queens, New York, to Italian immigrants. After working in his family''s agriculture business, he moved to Los Angeles in the 1930s to enter the film industry, starting as a mailroom clerk and working his way up through assistant director roles at 20th Century Fox. Following service in the United States Navy during World War II, Broccoli relocated to London in the early 1950s and co-founded Warwick Films with producer Irving Allen. The company produced a series of successful adventure pictures for Columbia Pictures, helping Broccoli build extensive production experience and crucial industry relationships across the United Kingdom. In 1961, Broccoli joined forces with Canadian producer Harry Saltzman, who held the film rights to Ian Fleming''s James Bond spy novels. Together, they established Eon Productions and holding company Danjaq, launching the film series with Dr. No in 1962 starring Sean Connery. The film became a massive box office hit and laid the foundation for the longest-running cinematic franchise in history. Broccoli co-produced nine Bond features with Saltzman through 1974''s The Man with the Golden Gun. When Saltzman sold his stake in 1975, Broccoli assumed full control of Eon Productions and served as the sole lead producer starting with The Spy Who Loved Me in 1977, guiding the series through major era transitions across five different Bond actors. Outside of the 007 series, Broccoli produced the beloved 1968 musical fantasy film Chitty Chitty Bang Bang, which was also adapted from an Ian Fleming book. In his later years, he gradually passed leadership of the Bond franchise to his daughter, Barbara Broccoli, and stepson, Michael G. Wilson, who served as co-producers alongside him on his final films. Recognized globally for his monumental impact on pop culture, Broccoli was awarded the Irving G. Thalberg Memorial Award by the Academy of Motion Picture Arts and Sciences in 1981. He passed away from heart failure in Beverly Hills on June 27, 1996, at the age of 87, leaving a legendary legacy as the driving force behind modern blockbuster cinema.',
       'American',
       '1909-04-05',
       '1996-06-27',
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Michael G. Wilson (A view to a kill, The living daylights, License to kill, Goldeneye, Tomorrow never dies, The world is not enough, Die another day, Casino Royale, Quantum of solace, Skyfall, Spectre, No time to die)
 */
INSERT INTO producers (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('e7bf2cd1-60f6-4540-8c28-b0b6315bf588'),
       'Michael G. Wilson',
       'Michael Gregg Wilson was born on January 21, 1942, in New York City. He pursued higher education in electrical engineering at Harvey Mudd College before studying law at Stanford University. After working as an engineer and later practicing international law in Washington, D.C., Wilson joined Eon Productions in 1972, working in the company''s legal department. He transitioned to creative duties as an assistant on The Spy Who Loved Me in 1977. He subsequently took on the role of executive producer for Moonraker, For Your Eyes Only, and Octopussy, while also co-writing the screenplays for several Bond features alongside veteran screenwriter Richard Maibaum. Wilson stepped up to co-produce A View to a Kill in 1985 alongside his stepfather, Eon co-founder Albert R. "Cubby" Broccoli. He continued as co-producer on the remaining Timothy Dalton entries, The Living Daylights and Licence to Kill, sole-authoring the screenplay for the latter. Following Cubby Broccoli''s passing, Wilson took full co-leadership of the franchise alongside his half-sister, Barbara Broccoli. Together, they guided Eon Productions through the Pierce Brosnan and Daniel Craig eras, modernizing the 007 brand for contemporary audiences while maintaining strict creative and production oversight across every entry. Beyond producing, Wilson is famous among fans for making subtle cameo appearances in almost every Eon Bond film since the late 1970s. In addition to his cinematic work, he is a dedicated collector and scholar of historic photography, co-founding the Wilson Centre for Photography in 1998. He was appointed a Commander of the Order of the British Empire for services to film and philanthropy, remaining one of the central figures in modern British cinema history.',
       'American-British',
       '1942-01-21',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);

/**
  Barbara Broccoli (Goldeneye, Tomorrow never dies, The world is not enough, Die another day, Casino Royale, Quantum of solace, Skyfall, Spectre, No time to die)
 */
INSERT INTO producers (id, name, biography, nationality, date_of_birth, date_of_death, created_at, updated_at)
VALUES (
       UUID_TO_BIN('ea4d72a4-0dc5-481b-9889-37d0d049555c'),
       'Barbara Broccoli',
       'Barbara Dana Broccoli was born on June 18, 1960, in Los Angeles, California, to veteran James Bond producer Albert R. "Cubby" Broccoli and actress Dana Wilson Broccoli. Growing up on the sets of the Bond films across the globe, she developed a deep, firsthand understanding of the motion picture industry from an early age. She attended Loyola Marymount University, where she earned a degree in communications and film. Broccoli officially began her career with Eon Productions as an assistant in the publicity department for The Spy Who Loved Me in 1977. She quickly moved up the production ladder, serving as an associate producer on The Living Daylights in 1987 and Licence to Kill in 1989. Broccoli stepped into the role of full lead producer alongside her half-brother, Michael G. Wilson, for GoldenEye in 1995. The film launched Pierce Brosnan''s tenure as 007 and marked a crucial turning point for the franchise, successfully proving that James Bond could thrive in the post-Cold War era. Following her father''s death in 1996, Broccoli and Wilson assumed total control of Eon Productions and Danjaq. Together, they navigated the series through major creative reinventions, most notably casting Daniel Craig for 2006''s Casino Royale, which rebooted the franchise to critical and commercial acclaim and culminated in record-breaking blockbusters like Skyfall and No Time to Die. Beyond her steward role over the 007 brand, Broccoli is an accomplished independent film and stage producer. Through her production outfit Astscamp, she has backed diverse film projects such as Film Stars Don''t Die in Liverpool, Till, and Othello. She is also a prolific theatre producer on the West End and Broadway, backing successful stage adaptations like Chitty Chitty Bang Bang, Once, Strangers on a Train, and Macbeth. A prominent advocate for equality and representation in the British film industry, Broccoli serves as Vice President of the BAFTA and was appointed Commander of the Order of the British Empire for services to film and drama.',
       'American-British',
       '1960-06-18',
       null,
       CURRENT_TIMESTAMP(6),
       CURRENT_TIMESTAMP(6)
);